css:
/* ÖkoInvest – gemeinsames Druck-Stylesheet aller Druckformate (wird per werkzeuge/bauen.py in jede Print-Format-JSON übernommen).
   Farben: Grün #669933, Navy #003473; Schriften: Manrope (Überschriften) / Inter mit Systemschrift-Fallbacks (keine externen Fonts, wkhtmltopdf offline). */
.print-format { font-family: Inter, "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 9.5pt; color: #1f2933; line-height: 1.45; padding: 0; }
.print-format h1, .print-format h2, .print-format h3, .oi-titel { font-family: Manrope, Inter, "Helvetica Neue", Arial, sans-serif; color: #003473; margin: 0; }
.oi-kopf { border-bottom: 3px solid #669933; padding-bottom: 8px; margin-bottom: 14px; }
.oi-ueberzeile { font-size: 7.5pt; letter-spacing: .12em; text-transform: uppercase; color: #669933; font-weight: 700; margin-bottom: 2px; }
.oi-titel { font-size: 17pt; font-weight: 800; line-height: 1.2; }
.oi-untertitel { font-size: 9.5pt; color: #52606d; margin-top: 3px; }
.oi-marke { font-family: Manrope, Inter, Arial, sans-serif; font-weight: 800; color: #003473; }
.oi-marke b { color: #669933; }
.oi-abschnitt { margin: 14px 0 6px; font-family: Manrope, Inter, Arial, sans-serif; font-size: 11pt; font-weight: 700; color: #003473; border-bottom: 1px solid #d9e2d0; padding-bottom: 3px; page-break-after: avoid; }
.oi-tabelle { width: 100%; border-collapse: collapse; margin: 4px 0 8px; }
.oi-tabelle th { text-align: left; font-size: 8pt; text-transform: uppercase; letter-spacing: .04em; color: #52606d; background: #f3f6ef; border-bottom: 1px solid #c9d6bb; padding: 5px 6px; }
.oi-tabelle td { border-bottom: 1px solid #e6ebe1; padding: 5px 6px; vertical-align: top; }
.oi-tabelle td.oi-zahl, .oi-tabelle th.oi-zahl { text-align: right; white-space: nowrap; }
.oi-daten { width: 100%; border-collapse: collapse; }
.oi-daten td { padding: 3px 6px 3px 0; vertical-align: top; }
.oi-daten td.oi-feld { width: 38%; color: #52606d; }
.oi-kacheln { width: 100%; border-collapse: separate; border-spacing: 6px 0; margin: 6px -6px 10px; }
.oi-kachel { background: #f3f6ef; border-radius: 10px; padding: 8px 10px; }
.oi-kachel .oi-wert { font-family: Manrope, Inter, Arial, sans-serif; font-size: 15pt; font-weight: 800; color: #003473; }
.oi-kachel .oi-bez { font-size: 7.5pt; color: #52606d; text-transform: uppercase; letter-spacing: .05em; }
.oi-hinweis { background: #f3f6ef; border-left: 3px solid #669933; padding: 7px 10px; margin: 8px 0; font-size: 8.5pt; }
.oi-warnung { background: #fff6e5; border-left: 3px solid #c98a00; padding: 7px 10px; margin: 8px 0; font-size: 8.5pt; }
.oi-vertraulich { border: 1.5px solid #003473; color: #003473; font-weight: 700; font-size: 8pt; letter-spacing: .08em; text-transform: uppercase; padding: 4px 8px; display: inline-block; border-radius: 6px; }
.oi-badge { display: inline-block; padding: 1px 7px; border-radius: 999px; font-size: 8pt; font-weight: 600; background: #e7efdd; color: #3d5c1f; }
.oi-badge.oi-rot { background: #fde8e8; color: #9b1c1c; }
.oi-badge.oi-gelb { background: #fff3d6; color: #7a5200; }
.oi-badge.oi-navy { background: #e3eaf4; color: #003473; }
.oi-text { white-space: pre-wrap; }
.oi-klein { font-size: 8pt; color: #52606d; }
.oi-absatz { margin: 0 0 7px; text-align: justify; }
.oi-unterschrift { width: 100%; margin-top: 34px; border-collapse: collapse; }
.oi-unterschrift td { width: 50%; padding: 0 18px 0 0; vertical-align: bottom; }
.oi-linie { border-top: 1px solid #1f2933; padding-top: 3px; font-size: 8pt; color: #52606d; }
.oi-protokoll { page-break-before: always; }
.oi-fuss { margin-top: 18px; border-top: 1px solid #d9e2d0; padding-top: 5px; font-size: 7.5pt; color: #7b8794; }
.oi-seitenumbruch { page-break-before: always; }
.oi-muster { position: relative; }
.oi-muster-stempel { border: 2px dashed #c98a00; color: #7a5200; padding: 6px 10px; font-weight: 700; margin-bottom: 10px; font-size: 8.5pt; }

html:
{#- ÖkoInvest – Störungsbericht (Plattform Stoerungsfall). Interne Kommentare nur, wenn „mit_intern“ nicht ausgeschaltet ist: Druck ist Backoffice-intern. -#}
{%- set f = oekoinvest_firma() -%}
{%- set a = oekoinvest_anlage_kurz(doc.anlage_id) -%}
{%- set kommentare = oekoinvest_json(doc.kommentare, []) -%}
{%- set verlauf = oekoinvest_json(doc.verlauf, []) -%}
{%- set farbe = {"kritisch": "oi-rot", "hoch": "oi-rot", "mittel": "oi-gelb"}.get(doc.schwere, "oi-navy") -%}
{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}
<div class="oi-kopf">
	<div class="oi-ueberzeile">Anlagen & Betrieb · Störung {{ doc.name }}</div>
	<div class="oi-titel">Störungsbericht: {{ doc.titel | e }}</div>
	<div class="oi-untertitel">Anlage {{ a.id | e }} · {{ a.titel | e }}{% if a.ort %} · {{ a.ort | e }}{% endif %}</div>
</div>
<p><span class="oi-badge {{ farbe }}">Schwere: {{ oekoinvest_label("schwere", doc.schwere) }}</span> <span class="oi-badge">{{ oekoinvest_label("stoerung_status", doc.status) }}</span></p>

<div class="oi-abschnitt">Ereignis</div>
<table class="oi-daten">
	<tr><td class="oi-feld">Erkennungsregel</td><td>{{ oekoinvest_label("regel", doc.regel) }}</td></tr>
	<tr><td class="oi-feld">Erkannt am</td><td>{{ oekoinvest_datum(doc.erkannt_am, true) }}</td></tr>
	<tr><td class="oi-feld">Zuletzt gemeldet</td><td>{{ oekoinvest_datum(doc.zuletzt_am, true) }} · {{ doc.anzahl or 1 }} Meldung(en)</td></tr>
	<tr><td class="oi-feld">Quittiert</td><td>{% if doc.quittiert_am %}{{ oekoinvest_datum(doc.quittiert_am, true) }} durch {{ oekoinvest_konto(doc.quittiert_von).name | e }}{% else %}noch nicht quittiert{% endif %}</td></tr>
	<tr><td class="oi-feld">Behoben</td><td>{{ oekoinvest_datum(doc.behoben_am, true) if doc.behoben_am else "offen" }}</td></tr>
	<tr><td class="oi-feld">Zuständig</td><td>{{ oekoinvest_konto(doc.zustaendig_id).name | e if doc.zustaendig_id else "–" }}</td></tr>
	{% if a.kwp %}<tr><td class="oi-feld">Anlagenleistung</td><td>{{ oekoinvest_zahl(a.kwp, 1) }} kWp{% if a.speicher_kwh %} · Speicher {{ oekoinvest_zahl(a.speicher_kwh, 0) }} kWh{% endif %}</td></tr>{% endif %}
</table>
{% if doc.text %}<div class="oi-abschnitt">Beschreibung</div><p class="oi-text">{{ doc.text | e }}</p>{% endif %}

{% if kommentare %}
<div class="oi-abschnitt">Kommentare</div>
<table class="oi-tabelle">
	<tr><th style="width:22%">Zeitpunkt</th><th style="width:22%">von</th><th>Text</th></tr>
	{% for k in kommentare %}<tr><td>{{ oekoinvest_datum(k.am, true) }}</td><td>{{ (k.vonName or "–") | e }}{% if k.intern %} <span class="oi-badge oi-navy">intern</span>{% endif %}</td><td class="oi-text">{{ k.text | e }}</td></tr>{% endfor %}
</table>
{% endif %}
{% if verlauf %}
<div class="oi-abschnitt">Verlauf</div>
<table class="oi-tabelle">
	<tr><th style="width:22%">Zeitpunkt</th><th>Ereignis</th></tr>
	{% for v in verlauf %}<tr><td>{{ oekoinvest_datum(v.am, true) }}</td><td>{{ v.text | e }}</td></tr>{% endfor %}
</table>
{% endif %}
<div class="oi-hinweis">Interner Bericht des Betriebs. Werte aus dem Monitoring (MQTT) sind nicht eichrechtskonform; maßgeblich für Abrechnungen sind die geeichten Zähler.</div>
<div class="oi-fuss">{{ f.name }} · {{ f.fn }} · Erstellt am {{ oekoinvest_datum(frappe.utils.now_datetime(), true) }} durch {{ frappe.session.user | e }}</div>
